31	// IDs are stable only inside one project session. Keeping the session in the
32	// value lets a command distinguish an unknown current-session ID from an ID
33	// invalidated by project replacement, even if Orca later reuses its raw ID.
34	template<class Tag> class ProjectScopedId
35	{
36	public:
37	    constexpr ProjectScopedId() = default;
38	    constexpr ProjectScopedId(ProjectSessionId session, std::uint64_t value) : m_session(session), m_value(value) {}
39	
40	    explicit constexpr operator bool() const { return static_cast<bool>(m_session) && m_value != 0; }
41	    constexpr ProjectSessionId session() const { return m_session; }
42	    constexpr std::uint64_t value() const { return m_value; }
43	
44	    friend constexpr bool operator==(ProjectScopedId lhs, ProjectScopedId rhs)
45	    {
46	        return lhs.m_session == rhs.m_session && lhs.m_value == rhs.m_value;
47	    }
48	    friend constexpr bool operator!=(ProjectScopedId lhs, ProjectScopedId rhs) { return !(lhs == rhs); }
49	    friend constexpr bool operator<(ProjectScopedId lhs, ProjectScopedId rhs)
50	    {
51	        return lhs.m_session < rhs.m_session || (lhs.m_session == rhs.m_session && lhs.m_value < rhs.m_value);
52	    }
53	
54	private:
55	    ProjectSessionId m_session;
56	    std::uint64_t    m_value{0};
57	};
