1145	    {
1146	        if (m_deliver) {
1147	            auto deliver = std::move(m_deliver);
1148	            deliver();
1149	        }
1150	    }
1151	
1152	    explicit operator bool() const { return static_cast<bool>(m_deliver); }
1153	
1154	private:
