433	OrcaWorkspaceAdapter::SliceState OrcaWorkspaceAdapter::current_slice_state() const
434	{
435	    SliceState state;
436	    // Whether a slice is running is part of what the plate holds, not merely
437	    // progress: starting one on an already-invalid plate changes neither the
438	    // valid flag nor the result id, so without it that transition publishes
439	    // nothing and no consumer ever learns the slice began.
440	    const bool slicing = m_plater.is_background_process_slicing();
441	    PartPlateList& plates = m_plater.get_partplate_list();
442	    for (int index = 0; index < plates.get_plate_count(); ++index) {
443	        PartPlate* plate = plates.get_plate(index);
444	        if (plate == nullptr) continue;
445	        const bool sliced = plate->is_slice_result_valid();
446	        const std::uint64_t result = sliced && !slicing && plate->get_slice_result() ?
447	            plate->get_slice_result()->id : 0;
448	        state.emplace(plate->id().id, PlateSlice{sliced, result, slicing});
449	    }
450	    return state;
451	}
