453	void OrcaWorkspaceAdapter::on_slice_status_changed(wxCommandEvent& event)
454	{
455	    event.Skip();
456	    wxASSERT(wxIsMainThread());
457	    // This event also fires whenever the native toolbar re-evaluates whether
458	    // Slice and Print are enabled, which happens on ordinary selection and
459	    // object changes. Publishing on all of those would advance the revision --
460	    // and add a history entry -- for nothing. Only a real change in what the
461	    // plates hold is a workspace change.
462	    SliceState state = current_slice_state();
463	    if (state == m_known_slice_state)
464	        return;
465	    // A plate that held a slice and no longer does was invalidated by whatever
466	    // the person just did. Recording it here, at the transition, is the only
467	    // moment the cause is still known.
468	    for (const auto& [id, now] : state) {
469	        const auto before = m_known_slice_state.find(id);
470	        if (before != m_known_slice_state.end() && before->second.sliced && !now.sliced)
471	            m_invalidated_by[id] = m_last_change_reason;
472	        else if (now.sliced)
473	            m_invalidated_by.erase(id);
474	    }
475	    m_known_slice_state = std::move(state);
476	    publish_change(WorkspaceChangeReasons::Slicing);
477	}
