479	WorkspaceSnapshot OrcaWorkspaceAdapter::snapshot() const
480	{
481	    wxASSERT(wxIsMainThread());
482	    WorkspaceSnapshot result;
483	    result.session  = m_session;
484	    result.revision = m_changes.revision();
485	
486	    // Read once: regional settings do not change while the app runs, and this
487	    // runs on every selection change.
488	    static const std::string currency = host_currency_code();
489	    result.currency = currency;
490	
491	    result.setup.project_name  = m_plater.get_project_name().ToUTF8().data();
492	    result.setup.project_dirty = m_plater.is_project_dirty();
493	    result.setup.presets_dirty = m_plater.is_presets_dirty();
494	    result.setup.project_path  = into_u8(m_plater.get_project_filename(".3mf"));
495	    if (const PresetBundle* presets = wxGetApp().preset_bundle; presets != nullptr) {
496	        result.setup.printer_preset = presets->printers.get_selected_preset().name;
497	        if (presets->printers.get_edited_preset().printer_technology() == ptFFF) {
498	            result.setup.process_preset = presets->prints.get_edited_preset().name;
499	            // One diff, used twice: snapshot() runs on every selection change.
500	            const std::vector<std::string> dirty = presets->prints.current_dirty_options();
501	            result.setup.process_preset_dirty = !dirty.empty();
502	            result.preset_deltas = preset_deltas_of(presets->prints, dirty);
503	        }
504	        if (!presets->filament_presets.empty())
505	            result.setup.filament_preset = presets->filament_presets.front();
506	    }
507	
508	    PartPlateList& plate_list = m_plater.get_partplate_list();
509	    const int active_index = plate_list.get_curr_plate_index();
510	    // One background process serves the whole application, so "running" is a
511	    // property of the workspace; during a slice-all the plate it names moves as
512	    // the run advances.
513	    result.slicing.running = m_plater.is_background_process_slicing();
514	    result.jobs            = m_jobs;
515	    if (result.slicing.running) {
516	        if (PartPlate* current = plate_list.get_plate(active_index); current != nullptr) {
517	            result.slicing.plate   = PlateId(m_session, current->id().id);
518	            const int percent      = current->get_slicing_percent();
519	            if (percent >= 0 && percent <= 100)
520	                result.slicing.percent = percent;
521	        }
522	    }
523	    result.plates.reserve(plate_list.get_plate_count());
524	    for (int index = 0; index < plate_list.get_plate_count(); ++index) {
525	        PartPlate* plate = plate_list.get_plate(index);
526	        WorkspacePlate projected_plate;
527	        projected_plate.id     = PlateId(m_session, plate->id().id);
528	        projected_plate.name   = plate->get_plate_name().empty() ? "Plate " + std::to_string(index + 1) : plate->get_plate_name();
529	        projected_plate.active = index == active_index;
530	        projected_plate.sliced = plate->is_slice_result_valid();
531	        const std::uint64_t plate_key = plate->id().id;
532	        if (projected_plate.sliced && !m_plater.is_background_process_slicing() && plate->get_slice_result()) {
533	            projected_plate.estimate        = estimate_of(*plate->get_slice_result());
534	            projected_plate.estimate_status = EstimateStatus::Current;
535	            // The figure this plate can currently defend, kept so a slice in
536	            // flight or an invalidated one still has something to show.
537	            if (projected_plate.estimate) m_last_estimate[plate_key] = *projected_plate.estimate;
538	        } else if (const auto remembered = m_last_estimate.find(plate_key); remembered != m_last_estimate.end()) {
539	            projected_plate.estimate        = remembered->second;
540	            projected_plate.estimate_status = m_plater.is_background_process_slicing() ?
541	                EstimateStatus::Recomputing : EstimateStatus::Stale;
542	            if (projected_plate.estimate_status == EstimateStatus::Stale) {
543	                if (const auto why = m_invalidated_by.find(plate_key); why != m_invalidated_by.end())
544	                    projected_plate.invalidated_by = why->second;
545	            }
546	        }
547	        const ModelObjectPtrs& objects = m_plater.model().objects;
548	        for (std::size_t object_index = 0; object_index < objects.size(); ++object_index) {
549	            WorkspaceObject object = project_object(m_session, *objects[object_index], *plate, static_cast<int>(object_index));
550	            if (!object.instances.empty())
551	                projected_plate.objects.emplace_back(std::move(object));
552	        }
553	        if (projected_plate.active)
554	            result.active_plate = projected_plate.id;
555	        result.plates.emplace_back(std::move(projected_plate));
556	    }
557	
558	    remember_current_ids();
559	
560	    Selection& selection = m_plater.canvas3D()->get_selection();
561	    if (selection.is_empty()) {
562	        result.selection_status = SelectionStatus::None;
563	    } else if (selection.is_single_full_object()) {
564	        const int index = selection.get_object_idx();
565	        if (index >= 0 && index < static_cast<int>(m_plater.model().objects.size())) {
566	            result.selection_status = SelectionStatus::Objects;
567	            result.selected_objects.emplace_back(m_session, m_plater.model().objects[index]->id().id);
568	        } else {
569	            result.selection_status = SelectionStatus::Unsupported;
570	        }
571	    } else if (selection.is_multiple_full_object()) {
572	        std::set<ObjectId> selected;
573	        for (const auto& object_instance : selection.get_selected_object_instances()) {
574	            const int index = object_instance.first;
575	            if (index >= 0 && index < static_cast<int>(m_plater.model().objects.size()))
576	                selected.emplace(m_session, m_plater.model().objects[index]->id().id);
577	        }
578	        result.selection_status = SelectionStatus::Objects;
579	        result.selected_objects.assign(selected.begin(), selected.end());
580	    } else {
581	        result.selection_status = SelectionStatus::Unsupported;
582	    }
583	
584	    result.can_undo = m_plater.can_undo_project();
585	    result.can_redo = m_plater.can_redo_project();
586	    return result;
587	}
