1546	        if (object.config.has("extruder"))
1547	            row.extruder = object.config.opt_int("extruder");
1548	        for (const ModelVolume* volume : object.volumes) {
1549	            if (volume->is_model_part()) ++row.parts;
1550	            else if (volume->is_modifier()) ++row.modifiers;
1551	            else if (volume->is_negative_volume()) ++row.negative_parts;
1552	            else if (volume->is_support_modifier()) ++row.support_volumes;
1553	        }
1554	        if (!object.instances.empty())
1555	            row.size = vec3(object.instance_bounding_box(0).size());
1556	        for (int plate = 0; plate < plates.get_plate_count(); ++plate)
1557	            for (std::size_t instance = 0; instance < object.instances.size(); ++instance)
1558	                if (plates.get_plate(plate)->contain_instance(static_cast<int>(index), static_cast<int>(instance))) {
1559	                    row.plates.push_back(PlateId(m_session, plates.get_plate(plate)->id().id));
1560	                    break;
1561	                }
1562	        result.push_back(std::move(row));
1563	    }
