101	// Time and material for one plate, read from the plate's own G-code result the
102	// same way Orca's preview and cost readouts do: volume per extruder times that
103	// filament's density and price. Nothing here is computed by JusPrin, so the
104	// card can never disagree with the number the slicer shows.
105	std::optional<SliceEstimate> estimate_of(const GCodeProcessorResult& result)
106	{
107	    SliceEstimate estimate;
108	    const auto& statistics = result.print_statistics;
109	    const auto& mode = statistics.modes[static_cast<std::size_t>(PrintEstimatedStatistics::ETimeMode::Normal)];
110	    estimate.print_time_seconds = mode.time > 0.f ? static_cast<std::uint32_t>(mode.time) : 0u;
111	
112	    double cost = 0.0;
113	    bool   every_filament_priced = true;
114	    for (const auto& [extruder, volume] : statistics.total_volumes_per_extruder) {
115	        // A slice that used an extruder Orca has no density for cannot be
116	        // weighed, and a partial weight presented as the total is worse than
117	        // no weight at all -- so the whole estimate goes.
118	        if (extruder >= result.filament_densities.size()) return std::nullopt;
119	        const double grams = volume * result.filament_densities[extruder] * 0.001;
120	        estimate.material_grams += grams;
121	        // A filament profile with no price reports zero, which is not a price.
122	        if (extruder < result.filament_costs.size() && result.filament_costs[extruder] > 0.f)
123	            cost += grams * result.filament_costs[extruder] * 0.001;
124	        else
125	            every_filament_priced = false;
126	    }
127	    // Money is the cost of the whole print or it is not shown. With one spool
128	    // priced and another not, a "total" would silently leave material out.
129	    estimate.has_cost      = every_filament_priced && cost > 0.0;
130	    estimate.material_cost = estimate.has_cost ? cost : 0.0;

