602	    }
603	
604	    wxString tooltip, auto_repaired_info, remaining_info;
605	
606	    // Create tooltip string, if there are errors
607	    if (stats.repaired()) {
608	        const int errors = get_repaired_errors_count(obj_idx, vol_idx);
609	        auto_repaired_info = format_wxstr(_L_PLURAL("%1$d error repaired", "%1$d errors repaired", errors), errors);
610	        tooltip += auto_repaired_info + "\n";
611	    }
612	    if (!stats.manifold()) {
613	        remaining_info = format_wxstr(_L_PLURAL("Error: %1$d non-manifold edge.", "Error: %1$d non-manifold edges.", stats.open_edges), stats.open_edges);
614	
615	        tooltip += _L("Remaining errors") + ":\n";
616	        tooltip += "\t" + format_wxstr(_L_PLURAL("%1$d non-manifold edge", "%1$d non-manifold edges", stats.open_edges), stats.open_edges) + "\n";
617	    }
618	
619	    if (sidebar_info) {
620	        *sidebar_info = stats.manifold() ? auto_repaired_info : (remaining_info + (stats.repaired() ? ("\n" + auto_repaired_info) : ""));
621	    }
622	
623	    if (non_manifold_edges)
624	        *non_manifold_edges = stats.open_edges;
625	
626	    if (!sidebar_info)
627	        tooltip += "\n" + _L("Click the icon to repair model object");
628	
629	    return { tooltip, get_warning_icon_name(stats) };
