29	    WorkspaceSnapshot snapshot() const override
30	    {
31	        WorkspaceSnapshot result = m_snapshot;
32	        result.session           = m_session;
33	        result.revision          = m_changes.revision();
34	        result.can_undo          = !m_undo.empty();
35	        result.can_redo          = !m_redo.empty();
36	        result.setup.process_preset = m_settings_available ? m_process_preset : "";
37	        result.setup.process_preset_dirty = m_settings.values != m_settings.preset_values;
38	        result.currency = m_currency;
39	        if (m_settings_available)
40	            for (const auto& [key, value] : m_settings.values) {
41	                const auto preset = m_settings.preset_values.find(key);
42	                if (preset == m_settings.preset_values.end() || preset->second == value) continue;
43	                const auto definition = std::find_if(m_settings.definitions.begin(), m_settings.definitions.end(),
44	                                                     [&](const auto& candidate) { return candidate.key == key; });
45	                result.preset_deltas.push_back(
46	                    {key, definition == m_settings.definitions.end() ? key : definition->label, preset->second, value});
47	            }
48	        for (auto& plate : result.plates)
49	            if (!plate.sliced) {
50	                // A fixture may describe an estimate the plate can no longer
51	                // defend -- recomputing or stale -- but never a current one.
52	                if (plate.estimate_status == EstimateStatus::Current) plate.estimate.reset();
53	                continue;
54	            } else {
55	                plate.estimate_status = EstimateStatus::Current;
56	                plate.invalidated_by.clear();
57	            }
58	        return result;
